/**
 * Single-line text entry (`design/components/input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentFill,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  resolveSlot,
  scope,
  useControlRef,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/input.module.css'

export type InputType = NonNullable<InputProps['type']>

export interface InputProps {
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  /**
   * The id of a label elsewhere on the page, such as `SettingsRow`'s one label for a whole row.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  autoComplete?: string
  /**
   * Native passthrough, for surfaces that already moved the user (a dialog's first field). Never
   * use it to take focus when a page loads.
   */
  autoFocus?: boolean
  /**
   * Shows a clear button while the field is non-empty. Clearing fires `onChange('')`.
   */
  clearable?: boolean
  /**
   * The clear button's accessible name. Defaults to `Clear`. Localized hosts pass their own.
   */
  clearLabel?: string
  /**
   * The native `<input>` itself, for an application binding that must read or restore state only
   * the element has, such as a caret or a selection, without a `querySelector` into the frame.
   * Merged with the member's own ref, so both get the same node, and `null` on unmount. Accepts
   * callback and object refs.
   */
  controlRef?: (element: HTMLInputElement | null) => void
  defaultValue?: string
  disabled?: boolean
  /**
   * The text is typed exactly: nothing corrects it, capitalises it or checks its spelling. For
   * text that must match letter for letter, such as a typed confirmation's phrase, because a
   * correction can change it while it is typed.
   */
  exact?: boolean
  /**
   * Leading, decorative.
   */
  icon?: IconRole
  id?: string
  invalid?: boolean
  max?: number
  maxLength?: number
  /**
   * `type="number"` only. Native passthrough, so the platform handles clamping and stepping.
   */
  min?: number
  name?: string
  /**
   * For touched validation, where apps mark a field dirty on leave. Native passthrough.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (value: string, event: Event) => void
  /**
   * IME composition end. `event.data` is the committed text.
   */
  onCompositionEnd?: (event: CompositionEvent) => void
  /**
   * Native passthrough for IME composition start. Composition events arrive as the platform
   * fires them, never suppressed and never repeated as a second change, so a binding that must
   * not commit mid-composition can wait between the two.
   */
  onCompositionStart?: (event: CompositionEvent) => void
  onFocus?: (event: FocusEvent) => void
  /**
   * Native passthrough: the selection moved (caret or range, by keyboard or pointer).
   * `selectionStart`, `selectionEnd` and `selectionDirection` are on `event.currentTarget`. The
   * member never moves the selection itself. Never fires for `email` or `number`, because the
   * platform gives those types no selection API.
   */
  onSelect?: (event: Event) => void
  placeholder?: string
  /**
   * Static text inside the frame, such as a currency mark, a unit or a domain. Strings only,
   * because a node here would duplicate `trailing`. They are `aria-hidden` and not part of the
   * value, so a unit that matters belongs in the label or description. The affix is only its
   * visual form.
   */
  prefix?: string
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  step?: number
  suffix?: string
  /**
   * Slot for a vocabulary element, such as a Badge or a ghost icon Button.
   */
  trailing?: JSX.Element
  type?: 'number' | 'search' | 'text' | 'email' | 'password' | 'url' | 'tel'
  value?: string
}

/** Single-line text entry. */
export default function Input(given: InputProps): JSX.Element {
  const props = mergeProps(
    {
      size: 'md',
      clearable: false,
      clearLabel: 'Clear',
      invalid: false,
      disabled: false,
      readOnly: false,
      type: 'text',
      autoFocus: false,
      exact: false,
    } as Defaults<
      InputProps,
      | 'size'
      | 'clearable'
      | 'clearLabel'
      | 'invalid'
      | 'disabled'
      | 'readOnly'
      | 'type'
      | 'autoFocus'
      | 'exact'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const control = useControlRef(() => props.controlRef)
    const trailingSlot = resolveSlot(() => props.trailing)
    const draft = createCell(props.defaultValue ?? '')
    const current = createDerived(() => props.value ?? draft.value)
    const showClear = createDerived(
      () => props.clearable && current.value !== '' && !props.disabled && !props.readOnly,
    )
    const effect1 = () => {
      void (props.autoFocus && control.value?.focus())
    }
    onMount(effect1)
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'Input',
        element: () => control.value,
        state: () => ({
          value: current.value,
          disabled: props.disabled,
          invalid: props.invalid,
          readonly: props.readOnly,
        }),
        actions: {
          fill: {
            argument: 'text',
            run: (value) =>
              (() => {
                if (props.type === 'password')
                  throw new Error('A person types a password; an agent does not.')
                if (props.readOnly) throw new Error('The field is read-only.')
                agentFill(control.value, value)
              })(),
          },
          clear: () =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              agentFill(control.value, '')
            })(),
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        class={styles.field}
        data-size={props.size}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-readonly={props.readOnly ? '' : undefined}
        data-member="input"
        onmousedown={($event: MouseEvent) =>
          !$event
            .composedPath()
            .some(
              (node) =>
                'nodeName' in node &&
                ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(String(node.nodeName)),
            ) && ($event.preventDefault(), control.value?.focus())
        }
      >
        {props.icon !== undefined ? (
          <span class={styles.leading}>
            <Icon name={props.icon} size={props.size} />
          </span>
        ) : null}
        {props.prefix !== undefined ? (
          <span class={styles.affix} aria-hidden="true">
            {props.prefix}
          </span>
        ) : null}
        {/* input */}
        <input
          class={styles.input}
          type={props.type}
          value={current.value}
          placeholder={props.placeholder}
          disabled={props.disabled}
          readonly={props.readOnly}
          min={props.min}
          max={props.max}
          step={props.step}
          name={props.name}
          id={props.id}
          autocomplete={props.autoComplete}
          autocorrect={props.exact ? 'off' : undefined}
          autocapitalize={props.exact ? 'off' : undefined}
          spellcheck={props.exact ? 'false' : undefined}
          maxlength={props.maxLength}
          aria-label={props['aria-label']}
          aria-labelledby={props['aria-labelledby']}
          aria-describedby={props['aria-describedby']}
          aria-required={props['aria-required']}
          aria-invalid={props.invalid ? true : undefined}
          oninput={($event: InputEvent) => (
            (draft.value = control.value?.value ?? ''),
            props.onChange?.(draft.value, $event)
          )}
          onblur={($event: FocusEvent) => props.onBlur?.($event)}
          onfocus={($event: FocusEvent) => props.onFocus?.($event)}
          onselect={($event: Event) => props.onSelect?.($event)}
          oncompositionstart={($event: CompositionEvent) => props.onCompositionStart?.($event)}
          oncompositionend={($event: CompositionEvent) => props.onCompositionEnd?.($event)}
          ref={control.attach}
        />
        {props.suffix !== undefined ? (
          <span class={styles.affix} aria-hidden="true">
            {props.suffix}
          </span>
        ) : null}
        {showClear.value ? (
          <button
            class={styles.clear}
            type="button"
            aria-label={props.clearLabel}
            onclick={($event: MouseEvent) => (
              (draft.value = ''),
              props.onChange?.('', $event),
              control.value?.focus()
            )}
          >
            <Icon name="clear" size={props.size} />
          </button>
        ) : null}
        {trailingSlot.filled() ? <span class={styles.trailing}>{trailingSlot()}</span> : null}
      </div>
    )
  })
}
